    apply (lap_of_run tm Cc true true cho_1RB1RD_0LC0RB_1LA1LB_1LC1LD B0_1RB1RD_0LC0RB_1LA1LB_1LC1LD B1_1RB1RD_0LC0RB_1LA1LB_1LC1LD 8 12 p j' [] []).
