      with (l := [SRotL 1; SWin 1; SCycL 5 0; SWin 4; SWinL 2]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1RD_0LC0RB_1LA1LB_1LC1LD
      with (l := [SRotL 1; SWin 1; SCycL 5 0; SWin 1]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1RD_0LC0RB_1LA1LB_1LC1LD
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1RD_0LC0RB_1LA1LB_1LC1LD
      with (l := [SRotL 1; SWin 1; SCycL 5 0; SWin 4; SWinL 3]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1RD_0LC0RB_1LA1LB_1LC1LD
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1RD_0LC0RB_1LA1LB_1LC1LD
      with (l := [SRotL 1; SWin 1; SCycL 5 0; SWin 4]).
