Lemma gen_1RB1RD_0LC0RB_1LA1LC_1LC1LD : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_000_010_0 q0 ++ [S1;S1]) [] i AI1_1RB1RD_0LC0RB_1LA1LC_1LC1LD) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (Alph_000_010_0.cview_some_Alph_000_010_0 v i q0 E) as (_ & H2).
  unfold Cin_1RB1RD_0LC0RB_1LA1LC_1LC1LD, cden, AI1_1RB1RD_0LC0RB_1LA1LC_1LC1LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S0;S0;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_1RB1RD_0LC0RB_1LA1LC_1LC1LD : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (8 * i + 4), (cden (Ap_Alph_000_010_0 q0 ++ [S1;S1]) [] i AI1_1RB1RD_0LC0RB_1LA1LC_1LC1LD).
  split; [lia|]. split; [| exact (gen_1RB1RD_0LC0RB_1LA1LC_1LC1LD v i q0 E)].
  rewrite (gsn_1RB1RD_0LC0RB_1LA1LC_1LC1LD v i q0 E).
  exact (srun_sound tm false true chn_1RB1RD_0LC0RB_1LA1LC_1LC1LD AI0_1RB1RD_0LC0RB_1LA1LC_1LC1LD AI1_1RB1RD_0LC0RB_1LA1LC_1LC1LD 8 4
           run_inner_1RB1RD_0LC0RB_1LA1LC_1LC1LD (Ap_Alph_000_010_0 q0 ++ [S1;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
