(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1RD_1LB1LC_0RD0LC_1RB1RA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Dp q0 ++ [S0]) [] 0 Z0_1RB1RD_1LB1LC_0RD0LC_1RB1RA /\
  cden (Dp q0 ++ [S0]) [] 0 Z1_1RB1RD_1LB1LC_0RD0LC_1RB1RA = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (DpCounter.cview_some_D p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB1RD_1LB1LC_0RD0LC_1RB1RA, cden, Z0_1RB1RD_1LB1LC_0RD0LC_1RB1RA, Z1_1RB1RD_1LB1LC_0RD0LC_1RB1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB1RD_1LB1LC_0RD0LC_1RB1RA : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Dp q0 ++ [S0]) [] j P0_1RB1RD_1LB1LC_0RD0LC_1RB1RA /\
  cden (Dp q0 ++ [S0]) [] j P1_1RB1RD_1LB1LC_0RD0LC_1RB1RA = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (DpCounter.cview_some_D p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB1RD_1LB1LC_0RD0LC_1RB1RA, cden, P0_1RB1RD_1LB1LC_0RD0LC_1RB1RA, P1_1RB1RD_1LB1LC_0RD0LC_1RB1RA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1RD_1LB1LC_0RD0LC_1RB1RA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB1RD_1LB1LC_0RD0LC_1RB1RA p q0 E) as (HA & HB).
    exists (0 * 0 + 4). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB1RD_1LB1LC_0RD0LC_1RB1RA Z0_1RB1RD_1LB1LC_0RD0LC_1RB1RA Z1_1RB1RD_1LB1LC_0RD0LC_1RB1RA 0 4
               run_z_1RB1RD_1LB1LC_0RD0LC_1RB1RA (Dp q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB1RD_1LB1LC_0RD0LC_1RB1RA p j' q0 E) as (HA & HB).
    exists (4 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1RD_1LB1LC_0RD0LC_1RB1RA P0_1RB1RD_1LB1LC_0RD0LC_1RB1RA P1_1RB1RD_1LB1LC_0RD0LC_1RB1RA 4 8
               run_p_1RB1RD_1LB1LC_0RD0LC_1RB1RA (Dp q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_1RB1RD_1LB1LC_0RD0LC_1RB1RA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1RD_1LB1LC_0RD0LC_1RB1RA.
