Lemma lapi_1RB1RD_1LC1LB_1RA0RD_0LB0RD : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
