               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB1RD_1LC1LB_1RA0RD_0LB0RD p j' q0 E) as (HA & HB).
    exists (4 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1RD_1LC1LB_1RA0RD_0LB0RD P0_1RB1RD_1LC1LB_1RA0RD_0LB0RD P1_1RB1RD_1LC1LB_1RA0RD_0LB0RD 4 8
