Lemma geo_1RB1RD_1LC1LB_1RA0RD_0LB0RD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RD_1LC1LB_1RA0RD_0LB0RD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (DpCounter.cview_none_D p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1RD_1LC1LB_1RA0RD_0LB0RD
             = (StD, (rep [S0;S0] (S j) ++ [S1;S1], S0, []))).
  { unfold cden, B1_1RB1RD_1LC1LB_1RA0RD_0LB0RD, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StD, ((rep [S0;S0] (S j) ++ [S1;S1]) ++ [S0], S0, []))).
