(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1RD_1LC1RA_1RA1LB_0RA0LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RD_1LC1RA_1RA1LB_0RA0LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1RD_1LC1RA_1RA1LB_0RA0LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1RD_1LC1RA_1RA1LB_0RA0LC p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB1RD_1LC1RA_1RA1LB_0RA0LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1RD_1LC1RA_1RA1LB_0RA0LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB1RD_1LC1RA_1RA1LB_0RA0LC t p (pow2 j)).
  - exists (4 * j + 12), (cden [] [] j BB1_1RB1RD_1LC1RA_1RA1LB_0RA0LC). split;
      [| exact (gbo_1RB1RD_1LC1RA_1RA1LB_0RA0LC j)].
    rewrite (gso_1RB1RD_1LC1RA_1RA1LB_0RA0LC p j E).
    exact (srun_sound tm true true chb_1RB1RD_1LC1RA_1RA1LB_0RA0LC B0_1RB1RD_1LC1RA_1RA1LB_0RA0LC BB1_1RB1RD_1LC1RA_1RA1LB_0RA0LC 4 12
             run_boot_1RB1RD_1LC1RA_1RA1LB_0RA0LC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB1RD_1LC1RA_1RA1LB_0RA0LC xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB1RD_1LC1RA_1RA1LB_0RA0LC j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1RD_1LC1RA_1RA1LB_0RA0LC : forall t, ~ In t pins_1RB1RD_1LC1RA_1RA1LB_0RA0LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1RD_1LC1RA_1RA1LB_0RA0LC.
  destruct t as [q b]; destruct q, b.
  - (* A0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1RD_1LC1RA_1RA1LB_0RA0LC (StA, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1RD_1LC1RA_1RA1LB_0RA0LC [SWin 8; SCycL 2 0; SWin 1; SWinL 2] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1RD_1LC1RA_1RA1LB_0RA0LC
      with (l := [SWin 3]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1RD_1LC1RA_1RA1LB_0RA0LC
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1RD_1LC1RA_1RA1LB_0RA0LC
      with (l := [SWin 2]).
    vm_compute; reflexivity.
  - (* C0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1RD_1LC1RA_1RA1LB_0RA0LC
      with (l := [SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1RD_1LC1RA_1RA1LB_0RA0LC
      with (l := [SWin 8]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1RD_1LC1RA_1RA1LB_0RA0LC
      with (l := [SWin 4]).
    vm_compute; reflexivity.
Qed.

