    apply (lap_of_run tm Cc true true cho_1RB1RD_1LC1RD_0RB0LC_1RA0LA B0_1RB1RD_1LC1RD_0RB0LC_1RA0LA B1_1RB1RD_1LC1RD_0RB0LC_1RA0LA 6 8 p j' [] []).
