Definition B1_1RB1RD_1LC1RD_0RB0LC_1RA0RD : sconf := mkC StC (mkS [] [S0;S0;S0] 1 1 [S1;S0;S1]) S0 (mkS [S1] [] 0 0 []).
(** ** The INNER anchor family -- Ap_Alph_000_001_00 at StB *)
Definition Cin_1RB1RD_1LC1RD_0RB0LC_1RA0RD (v : positive) : cconf := (StB, (Ap_Alph_000_001_00 v ++ [S0;S0;S1], S0, [S0;S1])).
Local Notation Cin := Cin_1RB1RD_1LC1RD_0RB0LC_1RA0RD.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_1RB1RD_1LC1RD_0RB0LC_1RA0RD : forall n, Ap_Alph_000_001_00 (pow2 n) = rep [S0;S0;S0] n ++ [S0;S0].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_1RB1RD_1LC1RD_0RB0LC_1RA0RD : sconf := mkC StB (mkS [] [S0;S0;S1] 1 0 [S0;S0;S0]) S0 (mkS [S0;S1] [] 0 0 []).
Definition AI1_1RB1RD_1LC1RD_0RB0LC_1RA0RD : sconf := mkC StB (mkS [] [S0;S0;S0] 1 0 [S0;S0;S1]) S0 (mkS [S0;S1] [] 0 0 []).
Definition chn_1RB1RD_1LC1RD_0RB0LC_1RA0RD : list lstep := [SWin 2; SCycL 3 0; SWin 6; SCycR 3; SWin 2].

Lemma run_inner_1RB1RD_1LC1RD_0RB0LC_1RA0RD : srun tm false true chn_1RB1RD_1LC1RD_0RB0LC_1RA0RD AI0_1RB1RD_1LC1RD_0RB0LC_1RA0RD = Some (AI1_1RB1RD_1LC1RD_0RB0LC_1RA0RD, 6, 10).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB1RD_1LC1RD_0RB0LC_1RA0RD : sconf := mkC StB (mkS [] [S0;S0;S0] 1 0 [S0;S0;S0;S0;S1]) S0 (mkS [S0;S1] [] 0 0 []).
Definition chb_1RB1RD_1LC1RD_0RB0LC_1RA0RD : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 3; SWinL 7; SCycR 3; SWin 2].

Lemma run_boot_1RB1RD_1LC1RD_0RB0LC_1RA0RD : srun tm true true chb_1RB1RD_1LC1RD_0RB0LC_1RA0RD B0_1RB1RD_1LC1RD_0RB0LC_1RA0RD = Some (BB1_1RB1RD_1LC1RD_0RB0LC_1RA0RD, 6, 13).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1RD_1LC1RD_0RB0LC_1RA0RD : sconf := mkC StB (mkS [] [S0;S0;S1] 1 0 [S0;S0;S0;S0;S1]) S0 (mkS [S0;S1] [] 0 0 []).
Definition che_1RB1RD_1LC1RD_0RB0LC_1RA0RD : list lstep := [SWin 2; SCycL 3 0; SWin 6; SCycR 3; SWin 1; SRotL 2; SFoldL 1].

Lemma run_exit_1RB1RD_1LC1RD_0RB0LC_1RA0RD : srun tm true true che_1RB1RD_1LC1RD_0RB0LC_1RA0RD BE0_1RB1RD_1LC1RD_0RB0LC_1RA0RD = Some (B1_1RB1RD_1LC1RD_0RB0LC_1RA0RD, 6, 9).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1RD_1LC1RD_0RB0LC_1RA0RD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_000_100_1 q0 ++ [S0;S1;S0]) [] 0 Z0_1RB1RD_1LC1RD_0RB0LC_1RA0RD /\
  cden (Ap_Alph_000_100_1 q0 ++ [S0;S1;S0]) [] 0 Z1_1RB1RD_1LC1RD_0RB0LC_1RA0RD = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_000_100_1.cview_some_Alph_000_100_1 p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB1RD_1LC1RD_0RB0LC_1RA0RD, cden, Z0_1RB1RD_1LC1RD_0RB0LC_1RA0RD, Z1_1RB1RD_1LC1RD_0RB0LC_1RA0RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB1RD_1LC1RD_0RB0LC_1RA0RD : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_000_100_1 q0 ++ [S0;S1;S0]) [] j P0_1RB1RD_1LC1RD_0RB0LC_1RA0RD /\
  cden (Ap_Alph_000_100_1 q0 ++ [S0;S1;S0]) [] j P1_1RB1RD_1LC1RD_0RB0LC_1RA0RD = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_000_100_1.cview_some_Alph_000_100_1 p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB1RD_1LC1RD_0RB0LC_1RA0RD, cden, P0_1RB1RD_1LC1RD_0RB0LC_1RA0RD, P1_1RB1RD_1LC1RD_0RB0LC_1RA0RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1RD_1LC1RD_0RB0LC_1RA0RD : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB1RD_1LC1RD_0RB0LC_1RA0RD p q0 E) as (HA & HB).
    exists (0 * 0 + 2). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB1RD_1LC1RD_0RB0LC_1RA0RD Z0_1RB1RD_1LC1RD_0RB0LC_1RA0RD Z1_1RB1RD_1LC1RD_0RB0LC_1RA0RD 0 2
               run_z_1RB1RD_1LC1RD_0RB0LC_1RA0RD (Ap_Alph_000_100_1 q0 ++ [S0;S1;S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB1RD_1LC1RD_0RB0LC_1RA0RD p j' q0 E) as (HA & HB).
    exists (6 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1RD_1LC1RD_0RB0LC_1RA0RD P0_1RB1RD_1LC1RD_0RB0LC_1RA0RD P1_1RB1RD_1LC1RD_0RB0LC_1RA0RD 6 8
               run_p_1RB1RD_1LC1RD_0RB0LC_1RA0RD (Ap_Alph_000_100_1 q0 ++ [S0;S1;S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_1RB1RD_1LC1RD_0RB0LC_1RA0RD : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1RD_1LC1RD_0RB0LC_1RA0RD.
Proof.
  intros p j E. destruct (Alph_000_100_1.cview_none_Alph_000_100_1 p j E) as (H1 & _).
  unfold Cc_1RB1RD_1LC1RD_0RB0LC_1RA0RD, cden, B0_1RB1RD_1LC1RD_0RB0LC_1RA0RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1RD_1LC1RD_0RB0LC_1RA0RD : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1RD_1LC1RD_0RB0LC_1RA0RD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1RD_1LC1RD_0RB0LC_1RA0RD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_000_100_1.cview_none_Alph_000_100_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1RD_1LC1RD_0RB0LC_1RA0RD
             = (StC, (rep [S0;S0;S0] (S j) ++ [S1;S0;S1], S0, [S1]))).
  { unfold cden, B1_1RB1RD_1LC1RD_0RB0LC_1RA0RD, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S0;S0;S0] (S j) ++ [S1;S0;S1]) ++ [S0], S0, [S1]))).
  { unfold Cc_1RB1RD_1LC1RD_0RB0LC_1RA0RD. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB1RD_1LC1RD_0RB0LC_1RA0RD. reflexivity.
Qed.

Lemma gsn_1RB1RD_1LC1RD_0RB0LC_1RA0RD : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ap_Alph_000_001_00 q0 ++ [S0;S0;S1]) [] i AI0_1RB1RD_1LC1RD_0RB0LC_1RA0RD.
Proof.
  intros v i q0 E. destruct (Alph_000_001_00.cview_some_Alph_000_001_00 v i q0 E) as (H1 & _).
  unfold Cin_1RB1RD_1LC1RD_0RB0LC_1RA0RD, cden, AI0_1RB1RD_1LC1RD_0RB0LC_1RA0RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S0;S0;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_1RB1RD_1LC1RD_0RB0LC_1RA0RD : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_000_001_00 q0 ++ [S0;S0;S1]) [] i AI1_1RB1RD_1LC1RD_0RB0LC_1RA0RD) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (Alph_000_001_00.cview_some_Alph_000_001_00 v i q0 E) as (_ & H2).
  unfold Cin_1RB1RD_1LC1RD_0RB0LC_1RA0RD, cden, AI1_1RB1RD_1LC1RD_0RB0LC_1RA0RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S0;S0;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_1RB1RD_1LC1RD_0RB0LC_1RA0RD : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (6 * i + 10), (cden (Ap_Alph_000_001_00 q0 ++ [S0;S0;S1]) [] i AI1_1RB1RD_1LC1RD_0RB0LC_1RA0RD).
  split; [lia|]. split; [| exact (gen_1RB1RD_1LC1RD_0RB0LC_1RA0RD v i q0 E)].
  rewrite (gsn_1RB1RD_1LC1RD_0RB0LC_1RA0RD v i q0 E).
  exact (srun_sound tm false true chn_1RB1RD_1LC1RD_0RB0LC_1RA0RD AI0_1RB1RD_1LC1RD_0RB0LC_1RA0RD AI1_1RB1RD_1LC1RD_0RB0LC_1RA0RD 6 10
           run_inner_1RB1RD_1LC1RD_0RB0LC_1RA0RD (Ap_Alph_000_001_00 q0 ++ [S0;S0;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_1RB1RD_1LC1RD_0RB0LC_1RA0RD : forall j, lift (cden [] [] j BB1_1RB1RD_1LC1RD_0RB0LC_1RA0RD) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB1RD_1LC1RD_0RB0LC_1RA0RD = (StB, (rep [S0;S0;S0] j ++ [S0;S0;S0;S0;S1], S0, [S0;S1]))).
  { unfold cden, BB1_1RB1RD_1LC1RD_0RB0LC_1RA0RD, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StB, (rep [S0;S0;S0] j ++ [S0;S0;S0;S0;S1], S0, [S0;S1]))).
  { unfold Cin_1RB1RD_1LC1RD_0RB0LC_1RA0RD. rewrite epow2_1RB1RD_1LC1RD_0RB0LC_1RA0RD.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB1RD_1LC1RD_0RB0LC_1RA0RD. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB1RD_1LC1RD_0RB0LC_1RA0RD : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB1RD_1LC1RD_0RB0LC_1RA0RD.
Proof.
  intro j.
  destruct (Alph_000_001_00.cview_none_Alph_000_001_00 (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB1RD_1LC1RD_0RB0LC_1RA0RD, cden, BE0_1RB1RD_1LC1RD_0RB0LC_1RA0RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB1RD_1LC1RD_0RB0LC_1RA0RD : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_1RB1RD_1LC1RD_0RB0LC_1RA0RD p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1RD_1LC1RD_0RB0LC_1RA0RD : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1RD_1LC1RD_0RB0LC_1RA0RD p (pow2 j)).
  - exists (6 * j + 13), (cden [] [] j BB1_1RB1RD_1LC1RD_0RB0LC_1RA0RD).
    split; [lia|]. split; [| exact (gbo_1RB1RD_1LC1RD_0RB0LC_1RA0RD j)].
    rewrite (gso_1RB1RD_1LC1RD_0RB0LC_1RA0RD p j E).
    exact (srun_sound tm true true chb_1RB1RD_1LC1RD_0RB0LC_1RA0RD B0_1RB1RD_1LC1RD_0RB0LC_1RA0RD BB1_1RB1RD_1LC1RD_0RB0LC_1RA0RD 6 13
             run_boot_1RB1RD_1LC1RD_0RB0LC_1RA0RD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 9), (cden [] [] j B1_1RB1RD_1LC1RD_0RB0LC_1RA0RD).
    split; [| exact (geo_1RB1RD_1LC1RD_0RB0LC_1RA0RD p j E)].
    rewrite (gxi_1RB1RD_1LC1RD_0RB0LC_1RA0RD j).
    exact (srun_sound tm true true che_1RB1RD_1LC1RD_0RB0LC_1RA0RD BE0_1RB1RD_1LC1RD_0RB0LC_1RA0RD B1_1RB1RD_1LC1RD_0RB0LC_1RA0RD 6 9
             run_exit_1RB1RD_1LC1RD_0RB0LC_1RA0RD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB1RD_1LC1RD_0RB0LC_1RA0RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1RD_1LC1RD_0RB0LC_1RA0RD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1RD_1LC1RD_0RB0LC_1RA0RD p j' E).
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB1RD_1LC1RD_0RB0LC_1RA0RD : stepn tmm_1RB1RD_1LC1RD_0RB0LC_1RA0RD 15 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_1RB1RD_1LC1RD_0RB0LC_1RA0RD 15 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_1RB1RD_1LC1RD_0RB0LC_1RA0RD 15 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB1RD_1LC1RD_0RB0LC_1RA0RD : existsb (fun tg => cfires tmm_1RB1RD_1LC1RD_0RB0LC_1RA0RD c0 15 tg) pins_1RB1RD_1LC1RD_0RB0LC_1RA0RD = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1RD_1LC1RD_0RB0LC_1RA0RD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1RD_1LC1RD_0RB0LC_1RA0RD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1RD_1LC1RD_0RB0LC_1RA0RD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1RD_1LC1RD_0RB0LC_1RA0RD p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1RD_1LC1RD_0RB0LC_1RA0RD : forall t, ~ In t pins_1RB1RD_1LC1RD_0RB0LC_1RA0RD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1RD_1LC1RD_0RB0LC_1RA0RD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1RD_1LC1RD_0RB0LC_1RA0RD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 3; SWinL 1]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1RD_1LC1RD_0RB0LC_1RA0RD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1RD_1LC1RD_0RB0LC_1RA0RD
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 3; SWinL 2]).
