    apply (lap_of_run tm Cc true true cho_1RB____0LB1RC_1LC1RD_1LB0RD B0_1RB____0LB1RC_1LC1RD_1LB0RD B1_1RB____0LB1RC_1LC1RD_1LB0RD 2 8 p j' [] []).
