    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB____0LC0LD_1RC1LD_0LB0RC (StB, S0)).
    intros p1 j1 E1.
    exact (firex_1RB____0LC0LD_1RC1LD_0LB0RC [SWin 4; SCycL 2 0; SWin 1; SWinL 2] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
