      with (l := [SWin 4; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB____0LC0LD_1RC1LD_0LB0RC
      with (l := []).
